  ];

  const carpeta =
    DriveApp.getFolderById(ID_CARPETA);

  let eliminados = 0;
  let noEncontrados = 0;

  cedulas.forEach(cedula => {

    const nombreArchivo =
      cedula + ".pdf";

    const archivos =
      carpeta.getFilesByName(nombreArchivo);

    if (archivos.hasNext()) {

      while (archivos.hasNext()) {

        const archivo =
          archivos.next();

        archivo.setTrashed(true);

        eliminados++;

        Logger.log(
          "Eliminado: " +
          nombreArchivo
        );
      }

    } else {

      noEncontrados++;

      Logger.log(
        "No encontrado: " +
        nombreArchivo
      );
    }
  });

  Logger.log(
    "=============================="
  );

  Logger.log(
    "PROCESO TERMINADO"
  );

  Logger.log(
    "PDF eliminados: " +
    eliminados
  );

  Logger.log(
    "PDF no encontrados: " +
    noEncontrados
  );

  Logger.log(
    "=============================="
  );
}

function eliminarTodosLosPDFs() {
  // ID de la carpeta especificada
  const ID_CARPETA = "18p-0C8iFFJ8Wl3_oi9g8BVBDlSG0MQHt";

  const carpeta = DriveApp.getFolderById(ID_CARPETA);

  // Buscar únicamente archivos cuyo tipo de contenido sea PDF
  const archivos = carpeta.getFilesByType(MimeType.PDF);

  let eliminados = 0;

  // Recorrer y enviar a la papelera cada PDF encontrado
  while (archivos.hasNext()) {
    const archivo = archivos.next();
    const nombreArchivo = archivo.getName();

    archivo.setTrashed(true);
    eliminados++;

    Logger.log("Eliminado: " + nombreArchivo);
  }

  Logger.log("==============================");
  Logger.log("PROCESO TERMINADO");
  Logger.log("Total de PDFs eliminados: " + eliminados);
  Logger.log("==============================");
}
